  ["Continuous Attack"] = "Ataque Contínuo",
  ["Attacks the current target 2 times in succession, dealing a total of <color=red>90% attack damage</color>."] = "Ataca o alvo atual 2 vezes seguidas, causando um total de <color=red> 90% de dano de ataque </color> .",
  ["Attacks the current target 3 times in succession, dealing a total of <color=red>90% attack damage</color>."] = "Ataca o alvo atual 3 vezes consecutivas, causando um total de <color=red> 90% de dano de ataque </color> .",
