  ["What about Marlow?"] = "E Marlow?",
  ["Marlow's farewell"] = "A despedida de Marlow",
  ["Marlow's dialogue"] = "Diálogo de Marlow",
  ["Marlow chose life. He is afraid of death."] = "Marlow escolheu a vida. Ele tem medo da morte.",
  ["Marlow, I think your teacher is happy."] = "Marlow, acho que seu professor está feliz.",
