  ["(0-08 Writing)"] = "(0-08 Escrita)",
  ["(2) 30 Defense"] = "(2) 30 Defesa",
  ["(2) 10 seconds before combat starts, additional 10% Defense;"] = "(2) 10 segundos antes do início do combate, 10% adicionais de Defesa;",
