  ["%s：%s\n%s：%s\n%s：%s\n%s：%s"] = "%s ： %s \n %s ： %s \n %s ： %s \n %s ： %s",
  ["Exit Vehicle"] = "Sair do veículo",
  ["A piece of cloth, a familiar pattern, this seems to be... part of a Nighthawk uniform?"] = "Um pedaço de pano, um padrão familiar, isso parece ser... parte de um uniforme Vigia Noturno?",
  ["One of the twenty-two divine pathways \nSequence 9: Corpse Collector, Sequence 8: Gravekeeper, Sequence 7: Spirit Medium, Sequence 6: Necromancer, Sequence 5: Gatekeeper, Sequence 4: Undying, Sequence 3: Ferryman, Sequence 2: Death Consul, Sequence 1: Pale Emperor, Sequence 0: Death"] = "Um dos vinte e dois caminhos divinos \n Sequência 9: Coletor de cadáveres, Sequência 8: Gravekeeper, Sequência 7: Spirit Medium, Sequência 6: Necromancer, Sequência 5: Gatekeeper, Sequência 4: Imortal, Sequência 3: Ferryman, Sequência 2: Death Consul, Sequência 1: Pale Imperador, Sequência 0: Morte",
  ["Final bloom of the garden"] = "Floração final do jardim",
  ["Hard · Believer Number One"] = "Difícil · Crente Número Um",
  ["One of the twenty-two divine pathways \nSequence 9: Sleepless, Sequence 8: Midnight Poet, Sequence 7: Nightmare, Sequence 6: Requiem, Sequence 5: Spirit Medium, Sequence 4: Nightwatcher, Sequence 3: Horror Bishop, Sequence 2: Servant of Concealment, Sequence 1: Misfortune Knight, Sequence 0: Darkness"] = "Um dos vinte e dois caminhos divinos \n Sequência 9: Sleepless, Sequência 8: Midnight Poet, Sequência 7: Nightmare, Sequência 6: Requiem, Sequência 5: Spirit Medium, Sequência 4: Nightwatcher, Sequência 3: Horror Bishop, Sequência 2: Servant of Concealment, Sequência 1: Cavaleiro do Infortúnio, Sequência 0: Escuridão",
  ["One of the twenty-two divine pathways \nSequence 9: Warrior, Sequence 8: Fighter, Sequence 7: Weapon Master, Sequence 6: Dawn Knight, Sequence 5: Guardian, Sequence 4: Demon Hunter, Sequence 3: Silver Knight, Sequence 2: Glory, Sequence 1: Hand of God, Sequence 0: God of Combat"] = "Um dos vinte e dois caminhos divinos \n Sequência 9: Guerreiro, Sequência 8: Lutador, Sequência 7: Mestre de Armas, Sequência 6: Cavaleiro da Aurora, Sequência 5: Guardião, Sequência 4: Caçador de Demônios, Sequência 3: Cavaleiro de Prata, Sequência 2: Glória, Sequência 1: Mão de Deus, Sequência 0: Deus do Combate",
  ["One of the twenty-two divine pathways \nSequence 9: Spectator, Sequence 8: Mind Reader, Sequence 7: Psychiatrist, Sequence 6: Hypnotist, Sequence 5: Dreamwalker, Sequence 4: Manipulator, Sequence 3: Dream Weaver, Sequence 2: Insight, Sequence 1: Author, Sequence 0: Visionary"] = "Um dos vinte e dois caminhos divinos \n Sequência 9: Espectador, Sequência 8: Leitor de Mentes, Sequência 7: Psiquiatra, Sequência 6: Hipnotizador, Sequência 5: Dreamwalker, Sequência 4: Manipulador, Sequência 3: Dream Weaver, Sequência 2: Insight, Sequência 1: Autor, Sequência 0: Visionário",
  ["One of the twenty-two divine pathways \nSequence 9: Bard, Sequence 8: Light Chaser, Sequence 7: Solar High Priest, Sequence 6: Notary, Sequence 5: Priest of Light, Sequence 4: Unshadowed, Sequence 3: Justice Mentor, Sequence 2: Light Chaser, Sequence 1: White Angel, Sequence 0: Sun"] = "Um dos vinte e dois caminhos divinos \n Sequência 9: Bardo, Sequência 8: Light Chaser, Sequência 7: Sumo Sacerdote Solar, Sequência 6: Notário, Sequência 5: Priest of Light, Sequência 4: Unshadowed, Sequência 3: Justice Mentor, Sequência 2: Light Chaser, Sequência 1: Anjo Branco, Sequência 0: Sol",
  ["One of the twenty-two divine pathways \nSequence 9: Mystery Pryer, Sequence 8: Pugilist, Sequence 7: Witch, Sequence 6: Scroll Professor, Sequence 5: Astrologer, Sequence 4: Mysticologist, Sequence 3: Prophet, Sequence 2: Sage, Sequence 1: Knowledge Emperor, Sequence 0: Hermit"] = "Um dos vinte e dois caminhos divinos \n Sequência 9: Espreitador de Mistério, Sequência 8: Pugilista, Sequência 7: Bruxa, Sequência 6: Professor de Pergaminho, Sequência 5: Astrólogo, Sequência 4: Misticologista, Sequência 3: Profeta, Sequência 2: Sábio, Sequência 1: Imperador do Conhecimento, Sequência 0: Eremita",
  ["One of the twenty-two divine pathways \nSequence 9: Seer, Sequence 8: Clown, Sequence 7: Magician, Sequence 6: Faceless, Sequence 5: Marionettist, Sequence 4: Bizarro Sorcerer, Sequence 3: Scholar of Yore, Sequence 2: Miracle Invoker, Sequence 1: Attendant of Mysteries, Sequence 0: The Fool"] = "Um dos vinte e dois caminhos divinos \n Sequência 9: Vidente, Sequência 8: Palhaço, Sequência 7: Mágico, Sequência 6: Sem rosto, Sequência 5: Marionetista, Sequência 4: Feiticeiro Bizarro, Sequência 3: Estudioso de Yore, Sequência 2: Invocador de Milagres, Sequência 1: Atendente de Mistérios, Sequência 0: O Louco",
  ["One of the twenty-two divine pathways \nSequence 9: Arbiter, Sequence 8: Sheriff, Sequence 7: Interrogator, Sequence 6: Judge, Sequence 5: Punishment Knight, Sequence 4: Law Magician, Sequence 3: Chaos Hunter, Sequence 2: Equilibrium, Sequence 1: Order Hand, Sequence 0: Justiciar"] = "Um dos vinte e dois caminhos divinos \n Sequência 9: Árbitro, Sequência 8: Xerife, Sequência 7: Interrogador, Sequência 6: Juiz, Sequência 5: Cavaleiro da Punição, Sequência 4: Mago da Lei, Sequência 3: Caçador de Caos, Sequência 2: Equilíbrio, Sequência 1: Ordem Mão, Sequência 0: Juiz",
  ["One of the twenty-two divine pathways \nSequence 9: Apprentice, Sequence 8: Trickmaster, Sequence 7: Astrologer, Sequence 6: Scribe, Sequence 5: Traveler, Sequence 4: Planeswalker, Sequence 3: Wanderer, Sequence 2: Door Master, Sequence 1: Key of Stars, Sequence 0: Door"] = "Um dos vinte e dois caminhos divinos \n Sequência 9: Aprendiz, Sequência 8: Malandro, Sequência 7: Astrólogo, Sequência 6: Escriba, Sequência 5: Viajante, Sequência 4: Planeswalker, Sequência 3: Andarilho, Sequência 2: Mestre da Porta, Sequência 1: Chave de estrelas, Sequência 0: Porta",
  ["Spend the late night with Dicy coffee"] = "Passe a madrugada com café Dicy",
  ["I can guide { { He | She } }."] = "Eu posso orientar {{Ele | Ela } }.",
  ["Not participated"] = "Não participou",
  ["Currency Consignment Delist Currency"] = "Moeda da lista de consignação de moeda",
  ["The sound of prayer pierces the dome and turns into a halo; piety echoes endlessly among the stone pillars of the temple."] = "O som da oração perfura a cúpula e se transforma em uma auréola; a piedade ecoa interminavelmente entre os pilares de pedra do templo.",
  ["Combing a neat hairstyle is the first lesson upon arriving at a new home. Love and faith watch over the children, making their souls pious and pure."] = "Pentear um penteado bem cuidado é a primeira lição ao chegar em uma nova casa. O amor e a fé zelam pelos filhos, tornando suas almas piedosas e puras.",
  ["Frequency"] = "Freqüência",
  ["The treatment is successful, wake up now."] = "O tratamento deu certo, acorde agora.",
  ["Fall for Me Too"] = "Apaixone-se por mim também",
  ["Forget it, after we got married, he changed; he's not as romantic as he used to be."] = "Esqueça, depois que nos casamos ele mudou; ele não é tão romântico como costumava ser.",
  ["When will I be able to become a qualified Seer..."] = "Quando poderei me tornar um Vidente qualificado...",
  ["Let's stop here, it'll be dangerous if we say any more."] = "Vamos parar por aqui, será perigoso se dissermos mais alguma coisa.",
  ["Which donkey-brained person dumped waste in the middle of the road?"] = "Qual pessoa com cérebro de burro jogou lixo no meio da estrada?",
  ["I think pure malt Langqi is the tavern's most important signature, right?"] = "Acho que o puro malte Langqi é a assinatura mais importante da taberna, certo?",
  ["Such low-quality perfume, I wouldn't even use it in the washroom before..."] = "Perfume de tão baixa qualidade que eu nem usava no banheiro antes...",
  ["A successful life! You need the Bread from Baker's Bakery!"] = "Uma vida de sucesso! Você precisa do Pão da Baker's Bakery!",
  ["Sir, what are you doing sneaking around crouching there?"] = "Senhor, o que você está fazendo se esgueirando agachado aí?",
  ["I remember where the stables were, where the well was, where the soldiers' barracks were, and where a plot of land had been cleared to grow potatoes and sweet potatoes..."] = "Lembro-me de onde ficavam os estábulos, onde ficava o poço, onde ficava o quartel dos soldados e onde foi aberto um terreno para o cultivo de batata e batata doce...",
  ["%s：%s。"] = "%s ： %s 。",
  ["Damn, why are you in a coffin?"] = "Droga, por que você está em um caixão?",
  ["Recommended Pairings"] = "Pares recomendados",
  ["A sweet, cloying scent spread from the furry head, causing all the Beyonders standing at the ready to feel a softening in their hearts."] = "Um cheiro doce e enjoativo se espalhou pela cabeça peluda, fazendo com que todos os Beyonders que estavam prontos sentissem um abrandamento em seus corações.",
  ["Auto-Switch Settings"] = "Configurações de troca automática",
  ["Beautiful flowers! Flowers picked just this morning!"] = "Lindas flores! Flores colhidas esta manhã!",
  ["If I cannot see tomorrow's night, please let the Goddess watch over my family and keep them safe."] = "Se eu não puder ver a noite de amanhã, por favor, deixe a Deusa cuidar da minha família e mantê-la segura.",
  ["It's not! What I said is true! You all heard it from others, but I saw it with my own eyes!"] = "Não é! O que eu disse é verdade! Todos vocês ouviram isso de outras pessoas, mas eu vi com meus próprios olhos!",
  ["Best of Five"] = "Melhor de cinco",
  ["After I go back this time, who knows when I'll be able to come to Tingen again."] = "Depois que eu voltar desta vez, quem sabe quando poderei voltar a Tingen.",
  ["Route %s"] = "Rota %s",
  ["Show bronze mirror"] = "Mostrar espelho de bronze",
  ["Brown bear"] = "Urso pardo",
  ["Rare Small Oil Painting"] = "Pintura a óleo pequena rara",
  ["This is truly a wonderful experience... Hmm, I have always looked forward to something like this. I mean, I love mystery, and I love miracles that transcend nature."] = "Esta é realmente uma experiência maravilhosa... Hmm, sempre desejei algo assim. Quer dizer, adoro mistério e adoro milagres que transcendem a natureza.",
  ["Rare Satin Pajamas"] = "Pijama de cetim raro",
  ["Rare Honey-Soaked Bacon"] = "Bacon mal passado embebido em mel",
  ["Rare Cedar Rum"] = "Rum de cedro raro",
  ["Golden branches and leaves weave a crown; immortality dwells deep within the shadows of the thicket. As vines entwine the gold leaf, the forest, too, shall bow its head."] = "Ramos e folhas douradas tecem uma coroa; a imortalidade habita nas profundezas das sombras do matagal. Assim como as vinhas se entrelaçam nas folhas de ouro, a floresta também inclinará a cabeça.",
  ["Dark Side of the City"] = "Lado Negro da Cidade",
  ["Fine Small Oil Painting"] = "Pintura a óleo pequena e fina",
  ["Satin Pajamas"] = "Pijama de cetim",
  ["Merchant Network Weaver"] = "Tecelão de Rede Mercante",
  ["Cocoa Milk Wine"] = "Vinho de Leite de Cacau",
  ["Sorry, but I don't think you'd fight a homeless person for a chair."] = "Desculpe, mas não acho que você lutaria com um sem-teto por uma cadeira.",
  ["Bearer of the Order Bulwark"] = "Portador do Baluarte da Ordem",
  ["Oh... baby... I've told you several times that I'm single..."] = "Ah... amor... já te disse diversas vezes que estou solteira...",
  ["Saint Selena Cathedral Top Specialty"] = "Especialidade principal da Catedral de Santa Selena",
  ["Tingen East Station Specialty Cultural Products"] = "Produtos Culturais Especiais da Estação Leste de Tingen",
  ["Tingen East Station Specialty Precision Instruments"] = "Instrumentos de precisão especializados da Estação Leste de Tingen",
  ["Advanced Occult Products"] = "Produtos Ocultos Avançados",
  ["Tingen East Station Specialty High-end Wine"] = "Vinho especial de alta qualidade da estação Tingen East",
  ["Snowy Mountain Specialty Rare Metals"] = "Metais raros especiais da Snowy Mountain",
  ["Basic Seasonings"] = "Temperos Básicos",
  ["Occult Processed Goods"] = "Produtos Ocultos Processados",
  ["Snowy Mountain Specialty High-grade Fur"] = "Pele de alta qualidade especial para Snowy Mountain",
  ["Golden Autumn Lake Processed Goods"] = "Produtos Processados ​​Golden Autumn Lake",
  ["Golden Autumn Lake Specialty Handicrafts"] = "Artesanato Especializado em Golden Autumn Lake",
  ["Ancient Castle Market Specialty"] = "Especialidade do Mercado do Castelo Antigo",
  ["The Fool that doesn't belong to this era, the mysterious ruler above the gray fog, the King of Yellow and Black who wields good luck..."] = "O Louco que não pertence a esta época, o governante misterioso acima da névoa cinzenta, o Rei do Amarelo e do Preto que exerce boa sorte...",
  ["<CostRed>{1,2,（Brand expired）}</> Pathway Specialization increased by <Mark> 250 </>. After more than <Mark> 2 </> seconds since last taking damage, Armor Break increased by <Mark> 70 </>, lasting <Mark> 5 </> seconds. \n Does not take effect when activating the set <Mark> Echo of Spirit and Knowledge </>."] = "<CostRed> {1,2,（Marca expirada）} </> Caminho Especialização aumentada em <Mark> 250 </> . Depois de mais de <Mark> 2 </> segundos desde o último dano recebido, Armor Break aumentou em <Mark> 70 </> , durando <Mark> 5 </> segundos. \n Não tem efeito ao ativar o conjunto <Mark> Echo of Spirit and Knowledge </> .",
  ["<Assistant_Title1>【I Want You, Mouse!】</>\n<Assistant_Title2>Quest Type: </><Assistant_Property2>Acting Story</>\n<Assistant_Title2>Quest Description: </>A commotion comes from the alley. A large tabby cat has cornered a small mouse, and the mouse is shivering in the corner.\n<Assistant_Title2>How to Accept: </>Advance to Sequence 8, head to {Location:[Tingen(887,1338)]|-11259;33864;-2462;2;5200002;0}, and observe <Assistant_Red> Cat and Mouse </> to accept the quest.\n<Assistant_Title2>Quest Rewards</>: Cognitive Experience, invoices, Adventure Medals, World Adventure Treasure progress"] = "<Assistant_Title1> 【Eu quero você, rato!】 </> \n <Assistant_Title2> Missão Tipo: </> <Assistant_Property2> História de atuação </> \n <Assistant_Title2> Missão Descrição: </> Uma comoção vem do beco. Um grande gato malhado encurralou um pequeno rato, e o rato está tremendo no canto.\n <Assistant_Title2> Como aceitar: </> Avance para Sequência 8, vá para {Local:[Tingen(887,1338)]|-11259;33864;-2462;2;5200002;0} e observe <Assistant_Red> Gato e Mouse </> para aceitar as missão .\n <Assistant_Title2> Missão Recompensas </>: Experiência Cognitiva, faturas, Medalhas de Aventura, progresso do Tesouro da Aventura Mundial",
  ["Obtain 1 Beyonder material with the { Horror Bishop } entry"] = "Obtenha 1 Beyonder material com a entrada { Horror Bishop }",
  ["Requiem Hair Strand"] = "Fio de Cabelo Réquiem",
  ["Approach and look"] = "Aproxime-se e olhe",
  ["The sweetest poison, the most bone-eroding honey. Will you just take a sip, or are you unable to stop?"] = "O veneno mais doce, o mel que mais desgasta os ossos. Você vai apenas tomar um gole ou não consegue parar?",
  ["Holy Radiance Bulwark"] = "Baluarte da Resplendor Sagrado",
  ["The Torrent of Knowledge sweeps through every gear of Steam, playing a unique melody in the roar—it is the longing to land on the moon, the anthem of victory in battle."] = "A Torrente do Conhecimento percorre cada equipamento do Steam, tocando uma melodia única no rugido – é o desejo de pousar na lua, o hino da vitória na batalha.",
  ["When Emperor Roselle landed on the moon, he did not ride this city of steam—but Steam Palace was born for it, and fell silent for it. Some great ideas, even if not chosen, are worth remembering."] = "Quando o Imperador Roselle pousou na Lua, ele não viajou nesta cidade de vapor – mas o Steam Palace nasceu para isso e ficou em silêncio por isso. Algumas ótimas ideias, mesmo que não escolhidas, merecem ser lembradas.",
  ["Steam Palace is roaring. After a city of steam broke free from its blueprints and gained life, that ceaseless core still beats for the moon-landing dream of a hundred years ago."] = "O Steam Palace está rugindo. Depois que uma cidade a vapor se libertou de seus projetos e ganhou vida, esse núcleo incessante ainda pulsa pelo sonho de pousar na Lua de cem anos atrás.",
  ["Born a pearl, even when fallen into the dust, it never lost a fraction of its luster—the most generous lie in the world is letting it mistakenly believe it could be buried."] = "Nascida como uma pérola, mesmo quando caiu no pó, nunca perdeu uma fração do seu brilho – a mentira mais generosa do mundo é deixá-la acreditar erroneamente que poderia ser enterrada.",
  ["Wow, look at this food! When the boss isn't looking, I'll sneak..."] = "Nossa, olha essa comida! Quando o chefe não está olhando, eu vou me esgueirar...",
  ["Confirm Position"] = "Confirmar posição",
  ["Burning Fragrance"] = "Fragrância Ardente",
  ["A set of Intis-style tableware, always ready on the dining table."] = "Um conjunto de louça estilo Intis, sempre pronto na mesa de jantar.",
  ["Buy and Save"] = "Compre e economize",
  ["Obtain 1 Beyonder material with the { Justice Mentor } entry"] = "Obtenha 1 Beyonder material com a entrada {Justiça Mentor}",
  ["Remaining sites in journey: "] = "Restantes locais em viagem:",
  ["Waiting for other team's match to end"] = "Esperando o fim da partida do outro time",
  ["Condition Group 3"] = "Grupo de Condição 3",
  ["The fluffy tail sways gently, becoming the focus of the entire audience at the climax of the ball. Among the stunned crowd, feel free to choose your satisfying prey."] = "A cauda fofa balança suavemente, tornando-se o foco de todo o público no clímax do baile. Entre a multidão atordoada, sinta-se à vontade para escolher sua presa satisfatória.",
  ["Poison ivy wraps around silence, and deep in the dark green lies a deadly elegance."] = "A hera venenosa envolve o silêncio, e nas profundezas do verde escuro reside uma elegância mortal.",
  ["Night and scarlet are the thorns wrapped around the long life of the Blood Clan—dangerous, beautiful, and stinging."] = "Noite e escarlate são os espinhos que envolvem a longa vida do Clã de Sangue – perigosos, belos e pungentes.",
  ["Where can I go to recruit a reliable head chef now?"] = "Onde posso recrutar um chefe de cozinha confiável agora?",
  ["Is this the Travel Stele? How do I activate it?"] = "Esta é a Estela de Viagem? Como faço para ativá-lo?",
  ["Hero - Turtle - Charge Mark tag"] = "Herói - Tartaruga - Etiqueta Charge Mark",
  [""] = "kZLOAEBpnoGpU3RhaW5EYXRhgbBmYXNoaW9uU3RhaW5JbmZvlpLNC6CBpUNvbG9ykYShWso9gQYloVjKPY9cKaF Zyj2BBiWhVwGSzQujgaVDb2xvcpGEoVrKPYEGJaFYyj2PXCmhWco9gQYloVcBks0LpIGlQ29sb3KRhKFayj2BBi WhWMo9j1wpoVnKPYEGJaFXAZLNC5+BpUNvbG9ykYShWso9gQYloVjKPY9cKaFZyj2BBiWhVwGSzQuigaVDb2xvc pGEoVrKPYEGJaFYyj2PXCmhWco9gQYloVcBks0LoYGlQ29sb3KRhKFayj2BBiWhWMo9j1wpoVnKPYEGJaFXAQ==",
  ["Switch character"] = "Trocar personagem",
  ["The greatest dancer in history vs. the greatest dancer of the modern era, who will win?"] = "A maior dançarina da história versus a maior dançarina da era moderna, quem vencerá?",
  ["Rare Coarse Wool Vest"] = "Colete de lã grossa rara",
  ["Yellow sand buries the past, His Gaze pierces through time, and the dream of the Blazing Sun has never dissipated."] = "A areia amarela enterra o passado, Seu Olhar atravessa o tempo e o sonho do Sol Ardente nunca se dissipou.",
  ["Never stop walking; trace the past and look toward tomorrow in the museum. Perhaps we are just silhouettes in the crevices of history."] = "Nunca pare de caminhar; traçar o passado e olhar para o amanhã no museu. Talvez sejamos apenas silhuetas nas fendas da história.",
  ["Is that lady a retired female soldier? But even among the believers of the Evernight Goddess, there are very few cases of being conscripted into the army..."] = "Essa senhora é uma soldado aposentada? Mas mesmo entre os crentes da Deusa da Noite Eterna, há muito poucos casos de recrutamento para o exército...",
  ["World of Order"] = "Mundo da Ordem",
  ["May the Goddess protect me, so I can live to receive this month's double salary."] = "Que a Deusa me proteja, para que eu possa viver para receber o dobro do salário deste mês.",
  ["Continuously fire multiple Air Bullets at enemies."] = "Dispare continuamente múltiplas balas de ar contra os inimigos.",
  ["Faceless Person"] = "Pessoa sem rosto",
